import{_ as e,o as s,c as n,a2 as i}from"./chunks/framework.DtFGJNng.js";const k=JSON.parse('{"title":"Memulai","description":"","frontmatter":{},"headers":[],"relativePath":"memulai.md","filePath":"memulai.md","lastUpdated":1794463556000}'),t={name:"memulai.md"};function l(d,a,p,o,u,r){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="memulai" tabindex="-1">Memulai <a class="header-anchor" href="#memulai" aria-label="Permalink to &quot;Memulai&quot;">​</a></h1><p>Halaman ini membawa kamu dari nol sampai satu work selesai: memasang deuz, menyiapkan proyek, menulis dokumen satu per satu, mengonfirmasi tiap dokumen, mengerjakan task, lalu meng-archive.</p><p>Contoh di semua halaman memakai produk fiktif: <strong>aplikasi perpustakaan</strong>, tempat anggota memesan buku yang sedang dipinjam orang lain.</p><h2 id="_1-pasang-deuz" tabindex="-1">1. Pasang deuz <a class="header-anchor" href="#_1-pasang-deuz" aria-label="Permalink to &quot;1. Pasang deuz&quot;">​</a></h2><p>deuz terdiri dari plugin Claude Code (Markdown dan YAML) dan CLI kecil berbahasa Go yang menjalankan aturan secara pasti. CLI cukup di-build sekali. Go 1.24+ hanya dibutuhkan untuk build; hasilnya satu binary tanpa runtime.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/ke/deuz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # menghasilkan bin/deuz, dipakai oleh skill</span></span></code></pre></div><p>Lalu pasang plugin-nya:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pasang dari checkout lokal (tersedia di setiap sesi baru)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/ke/deuz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deuz@deuz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># atau hanya untuk satu sesi</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plugin-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/ke/deuz</span></span></code></pre></div><p>Skill deuz berawalan <code>deuz:</code>, misalnya <code>/deuz:new</code>. Setelah mengubah skill atau aturan di checkout, buka sesi baru agar perubahannya terbaca.</p><p>Kalau ingin memakai CLI langsung di terminal, tambahkan <code>bin/</code> ke <code>PATH</code> atau panggil dengan path lengkapnya. Skill akan mencari CLI di <code>PATH</code>, lalu di <code>bin/</code> plugin.</p><h2 id="_2-siapkan-proyek" tabindex="-1">2. Siapkan proyek <a class="header-anchor" href="#_2-siapkan-proyek" aria-label="Permalink to &quot;2. Siapkan proyek&quot;">​</a></h2><p>Di repository proyekmu, minta agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deuz:init</span></span></code></pre></div><p>Agent membaca README dan struktur repo, lalu menanyakan satu per satu:</p><ul><li><strong>peran yang ada di tim</strong> dan nama lokalnya (<code>analyst</code>, <code>designer</code>, <code>frontend</code>, <code>backend</code>, <code>qa</code>), serta apakah pekerjaan perlu <strong>persetujuan bisnis</strong> (role <code>business</code>);</li><li><strong>homes</strong>: tempat sumber kebenaran permanen, yaitu spec perilaku (bawaan <code>deuz/specs</code>), file desain, dan definisi API, atau <code>null</code> kalau tidak ada;</li><li><strong>bahasa</strong> isi dokumen (misalnya <code>id</code>).</li></ul><p>Hasilnya <code>deuz/config.yaml</code>. Kalau dijalankan langsung lewat CLI, perintahnya seperti ini:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ deuz init --role analyst=Analyst --role designer=Designer --role frontend=Frontend --role backend=Backend --role qa=QA --role business=&quot;Business stakeholders&quot; --home specs=deuz/specs --home design=design --home api=api/openapi.yaml --language id</span></span>
<span class="line"><span>Created deuz/config.yaml (schema default, roles: analyst, designer, frontend, backend, qa, business).</span></span>
<span class="line"><span>Next: edit context in deuz/config.yaml, then \`deuz new &lt;work&gt;\`.</span></span></code></pre></div><p>Setelah itu isi <code>context</code> di <code>config.yaml</code> dengan gambaran singkat proyek (stack, struktur folder, konvensi). Agent membaca bagian ini setiap kali menulis dokumen. Pilihan lain dijelaskan di <a href="./kustomisasi">Kustomisasi</a>.</p><h2 id="_3-mulai-satu-work" tabindex="-1">3. Mulai satu work <a class="header-anchor" href="#_3-mulai-satu-work" aria-label="Permalink to &quot;3. Mulai satu work&quot;">​</a></h2><p>Satu <strong>work</strong> adalah satu fitur atau satu perubahan. Minta agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deuz:new pemesanan-buku</span></span></code></pre></div><p>Agent menanyakan tujuan dan <strong>jenis work</strong>: <code>feature</code>, <code>enhancement</code>, <code>bug</code>, <code>tech</code>, atau <code>chore</code>. Lalu ia membuat folder <code>deuz/work/pemesanan-buku/</code> beserta <code>.deuz.yaml</code>, dan menampilkan status awal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>deuz/work/pemesanan-buku  (schema: default)</span></span>
<span class="line"><span>  ○ proposal        available</span></span>
<span class="line"><span>  · specs           locked        (waiting for proposal)</span></span>
<span class="line"><span>  · ui-design       locked        (waiting for specs)</span></span>
<span class="line"><span>  · api-contract    locked        (waiting for specs, ui-design)</span></span>
<span class="line"><span>  · tasks-backend   locked        (waiting for specs, api-contract)</span></span>
<span class="line"><span>  · tasks-frontend  locked        (waiting for specs, ui-design, api-contract)</span></span>
<span class="line"><span>  · tasks-test      locked        (waiting for specs, ui-design, api-contract)</span></span></code></pre></div><p>Hanya proposal yang bisa ditulis. Dokumen lain terkunci sampai dokumen yang dibutuhkannya selesai.</p><h2 id="_4-tulis-dokumen-konfirmasi-ulangi" tabindex="-1">4. Tulis dokumen, konfirmasi, ulangi <a class="header-anchor" href="#_4-tulis-dokumen-konfirmasi-ulangi" aria-label="Permalink to &quot;4. Tulis dokumen, konfirmasi, ulangi&quot;">​</a></h2><p>Polanya selalu sama, untuk setiap dokumen:</p><ol><li><strong>Tulis</strong>: <code>/deuz:continue</code> (atau <code>/deuz:continue specs</code> untuk dokumen tertentu). Agent mengambil template dan instruksi dokumen itu, membaca dokumen sebelumnya, lalu menulis.</li><li><strong>Periksa</strong>: baca hasilnya, perbaiki bersama agent sampai benar.</li><li><strong>Konfirmasi</strong>: pemilik dokumen menjalankan <code>/deuz:ready &lt;dokumen&gt; --as &lt;peran&gt;</code>. Begitu semua pemilik mengonfirmasi, dokumen berikutnya terbuka.</li></ol><p>Untuk proposal sebuah <code>feature</code> dengan role <code>business</code> aktif, konfirmasi analyst saja belum cukup:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ deuz ready proposal --as analyst</span></span>
<span class="line"><span>proposal confirmed by Analyst; still waiting for Business stakeholders.</span></span></code></pre></div><p>Setelah rapat dengan stakeholder, analyst mencatat hasilnya di proposal (bagian Pertanyaan &amp; keputusan dan Persetujuan), lalu mengonfirmasi atas nama bisnis:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ deuz ready proposal --as business</span></span>
<span class="line"><span>proposal is ready (confirmed by Analyst, Business stakeholders).</span></span>
<span class="line"><span>Areas recorded: frontend, backend, api, business</span></span>
<span class="line"><span>Now available: specs</span></span></code></pre></div><p>Lanjutkan dengan pola yang sama: <code>specs</code> (analyst), <code>ui-design</code> (designer), <code>api-contract</code> (backend dan frontend), lalu <code>tasks-backend</code>, <code>tasks-frontend</code>, dan <code>tasks-test</code> yang dikerjakan paralel. Dokumen yang tidak relevan otomatis di-skip. Misalnya, kalau proposal tidak mencentang area <code>design</code>, <code>ui-design</code> di-skip.</p><p>Kapan saja kamu bisa melihat posisi work dengan <code>/deuz:status</code>.</p><h2 id="_5-kerjakan-task" tabindex="-1">5. Kerjakan task <a class="header-anchor" href="#_5-kerjakan-task" aria-label="Permalink to &quot;5. Kerjakan task&quot;">​</a></h2><p>Setelah daftar task dikonfirmasi, engineer atau QA meminta agent:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deuz:apply tasks-backend</span></span></code></pre></div><p>Agent mengerjakan task satu per satu dan mencentang (<code>- [x]</code>) task yang sudah terbukti selesai lewat cara verifikasi yang tertulis di task itu. Mencentang task tidak membatalkan konfirmasi daftar task.</p><h2 id="_6-archive" tabindex="-1">6. Archive <a class="header-anchor" href="#_6-archive" aria-label="Permalink to &quot;6. Archive&quot;">​</a></h2><p>Setelah semua dokumen <code>ready</code> (atau <code>skipped</code>) dan semua task tercentang:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/deuz:archive</span></span></code></pre></div><p>deuz menggabungkan delta spec ke spec permanen di <code>deuz/specs/</code>, menjalankan promote yang tersisa, lalu memindahkan work ke <code>deuz/work/archive/&lt;tanggal&gt;-pemesanan-buku/</code>. Sejak saat itu <code>deuz/specs/</code> menggambarkan sistem sebagaimana sudah dibangun.</p><h2 id="selanjutnya" tabindex="-1">Selanjutnya <a class="header-anchor" href="#selanjutnya" aria-label="Permalink to &quot;Selanjutnya&quot;">​</a></h2><ul><li><a href="./konsep-singkat">Konsep singkat</a> untuk memahami istilah yang baru saja kamu pakai.</li><li><a href="./alur-kerja">Alur kerja</a> untuk jalur yang lebih ringan (bug fix, perubahan teknis).</li><li><a href="./contoh">Contoh</a> untuk melihat isi dokumen sungguhan.</li></ul>`,43)])])}const h=e(t,[["render",l]]);export{k as __pageData,h as default};
